const defaultPage:any={platform:'platformDashboard',company:'companyDashboard',project:'dashboard'}
function tag(v:string){return tags[v]||[v||'-','info']}
function questionOptions(options:string){return (options||'').replace(/\s+(?=[A-ZＡ-Ｚ][.、．])/gi,'；').split(/[；;\n]/).map(x=>x.trim()).filter(Boolean)}
function formatDateTime(v:string){return v?String(v).replace('T',' ').slice(0,19):'-'}
function appBase(){const base=import.meta.env.BASE_URL.replace(/\/$/,'');return base==='/'?'':base}
function pagePath(k=active.value,ctx=scope.value){if(ctx.type==='platform')return `/platform/${k}`;if(ctx.type==='company')return `/company/${ctx.id}/${k}`;return `/project/${ctx.id}/${k}`}
function updateUrl(k=active.value){const path=appBase()+pagePath(k);if(location.pathname!==path)history.pushState({},'',path)}
function parseRoute(path=routePath){const parts=path.split('/').filter(Boolean);if(parts[0]==='platform')return {type:'platform',key:parts[1]||'platformDashboard'};if(parts[0]==='company'&&parts[1])return {type:'company',id:Number(parts[1]),key:parts[2]||'companyDashboard'};if(parts[0]==='project'&&parts[1])return {type:'project',id:Number(parts[1]),key:parts[2]||'dashboard'};return null}
function canEnterCompany(id:number){return session.role==='SUPER_ADMIN'||session.companyLevelCompanyIds.includes(Number(id))}
async function restoreFromUrl(){const r:any=parseRoute(location.pathname.startsWith(import.meta.env.BASE_URL)?location.pathname.slice(import.meta.env.BASE_URL.length-1):location.pathname);if(!r)return false;if(r.type==='platform'){if(session.role!=='SUPER_ADMIN')return false;scope.value={type:'platform',id:null,companyId:null,name:'平台级'};session.setContext(scope.value);await select(r.key,false);return true}if(r.type==='company'){if(!canEnterCompany(r.id))return false;const c=scopeOptions.value.companies.find((x:any)=>x.id===r.id);if(!c)return false;scope.value={type:'company',id:c.id,companyId:c.id,name:c.name};session.setContext(scope.value);await select(r.key,false);return true}if(r.type==='project'){const p=scopeOptions.value.projects.find((x:any)=>x.id===r.id);if(!p)return false;scope.value={type:'project',id:p.id,companyId:p.companyId,name:p.projectName,companyName:scopeOptions.value.companies.find((c:any)=>c.id===p.companyId)?.name};session.setContext(scope.value);await select(r.key,false);return true}return false}
async function login(){loading.value=true;try{const d:any=await post('/auth/login',loginForm.value);session.login(d);logged.value=true;await loadScopeOptions();if(!await restoreFromUrl()){if(d.role==='SUPER_ADMIN')await select('platformDashboard');else {const company=scopeOptions.value.companies.find((x:any)=>canEnterCompany(x.id));if(company)chooseScope('company',company);else if(scopeOptions.value.projects[0])chooseScope('project',scopeOptions.value.projects[0])}}ElMessage.success('欢迎进入 BuildGuard')}catch(e:any){ElMessage.error(e.message)}finally{loading.value=false}}
async function select(k:string,pushUrl=true){if(!menuItems.value.some((item:any)=>item.key===k)){k=defaultPage[scope.value.type];if(pushUrl)ElMessage.error('当前账号没有该模块访问权限')}active.value=k;search.value='';if(pushUrl)updateUrl(k);if(k==='screen'&&scope.value.type==='project'){window.open(`${import.meta.env.BASE_URL}screen/project/${scope.value.id}`,'_blank','noopener,noreferrer');return}if(k==='platformDashboard'){dashboard.value=await get('/platform/overview');return}if(k==='companyDashboard'){[dashboard.value,dashboardProjects.value,dashboardHealth.value]=await Promise.all([get(`/company-dashboard/overview?companyId=${scope.value.id}`),get(`/company-dashboard/projects?companyId=${scope.value.id}`),get(`/company-dashboard/project-health?companyId=${scope.value.id}`)]);return}if(k==='projectHealth'){rows.value=await get(`/company-dashboard/project-health?companyId=${scope.value.id}`);return}if(k==='dashboard'){await loadDashboard();return}if(k==='projectSettings'){await loadProjectConfig();return}if(k==='alarmCenter'){rows.value=await get(`/alarm-center?projectId=${scope.value.id}`);return}if(k==='towerCranes'){await loadTowerMonitor();return}if(['dustNoise','hoists','videoAi'].includes(k)){await loadGenericMonitor();return}if(['floorPlan','bimModel'].includes(k)){await loadSpatial();return}if(k==='dailyAttendance'){await loadDailyAttendance();return}if(k==='attendanceStat'){await loadAttendanceStats();return}if(k==='openAccess'){await loadOpenAccess();return}if(['companyWorkers','companyAttendance'].includes(k)){rows.value=[];return}if(k==='teams')projectUnits.value=await get(`/participant-units?projectId=${scope.value.id}`);if(k==='companyUsers')scopeRoles.value=await get(`/company-roles?companyId=${scope.value.id}`);if(k==='projectUsers')scopeRoles.value=await get(`/project-roles?projectId=${scope.value.id}`);if(k==='questions'){rows.value=await get(`/education/questions?projectId=${scope.value.id}`);return}if(k==='permissions'){[projectWorkers.value,projectAreas.value,rows.value]=await Promise.all([get(`/workers?projectId=${scope.value.id}`),get(`/project-areas?projectId=${scope.value.id}`),get(`/worker-area-permissions?projectId=${scope.value.id}`)]);return}if(k==='trainingTasks')[educationCourses.value,projectWorkers.value,projectTeams.value]=await Promise.all([get(`/education/courses?projectId=${scope.value.id}`),get(`/workers?projectId=${scope.value.id}`),get(`/teams?projectId=${scope.value.id}`)]);if(k==='devices')projectAreas.value=await get(`/project-areas?projectId=${scope.value.id}`);if(map[k]){let url=map[k];if(k==='dictionaries')url+=`?type=${dictionaryType.value}`;if(k==='platformUsers'&&companyFilter.value)url+=`?companyId=${companyFilter.value}`;if(['companyUsers','companyRoles'].includes(k))url+=`?companyId=${scope.value.id}`;if(scope.value.type==='project'&&k!=='companies')url+=`${url.includes('?')?'&':'?'}projectId=${scope.value.id}`;if(k==='blacklists')url+=`&status=BLACKLIST`;if(scope.value.type==='company'&&k==='projects')url+=`?companyId=${scope.value.id}`;rows.value=await get(url)}else rows.value=[]}
async function loadDashboard(){[dashboard.value,rows.value,todos.value]=await Promise.all([get(`/project-dashboard/overview?projectId=${scope.value.id}`),get(`/attendance/records?projectId=${scope.value.id}`),get(`/work-todos?projectId=${scope.value.id}`)]);await nextTick();drawCharts()}
async function loadAttendanceStats(){attendanceStats.value=await get(`/attendance/stat?projectId=${scope.value.id}`)}
async function loadDailyAttendance(){dailyAttendance.value=await get(`/attendance/daily-detail?projectId=${scope.value.id}&date=${dailyAttendanceDate.value}`)}
async function loadProjectConfig(){projectConfigLoading.value=true;try{projectConfig.value=await get(`/project-runtime-config?projectId=${scope.value.id}`)}finally{projectConfigLoading.value=false}}
async function saveProjectConfig(){try{await post('/project-runtime-config',{...projectConfig.value,projectId:scope.value.id});ElMessage.success('项目配置已保存')}catch(e:any){ElMessage.error(e.message)}}
function openAttendanceRule(row?:any){editingAttendanceRule.value=!!row;attendanceRuleForm.value=row?{...row}:{projectId:scope.value.id,name:'项目标准班次',workStartTime:'09:00',workEndTime:'18:00',lateGraceMinutes:0,earlyGraceMinutes:0,overtimeThresholdMinutes:0,crossDay:false,status:'ACTIVE'};attendanceRuleDialog.value=true}
async function saveAttendanceRule(){try{if(editingAttendanceRule.value)await put(`/attendance-rules/${attendanceRuleForm.value.id}`,attendanceRuleForm.value);else await post('/attendance-rules',attendanceRuleForm.value);attendanceRuleDialog.value=false;await select('attendanceRules');ElMessage.success('考勤规则已保存')}catch(e:any){ElMessage.error(e.message)}}
async function deleteAttendanceRule(row:any){try{await ElMessageBox.confirm(`确定删除规则“${row.name}”吗？`,'删除考勤规则',{type:'warning'});await del(`/attendance-rules/${row.id}`);await select('attendanceRules');ElMessage.success('考勤规则已删除')}catch(e:any){if(e!=='cancel'&&e!=='close')ElMessage.error(e.message)}}
function openDictionary(row?:any){editingDictionary.value=!!row;dictionaryForm.value=row?{...row}:{dictType:dictionaryType.value,code:'',name:'',sortOrder:0,status:'ACTIVE'};dictionaryDialog.value=true}
async function saveDictionary(){try{if(editingDictionary.value)await put(`/dictionaries/${dictionaryForm.value.id}`,dictionaryForm.value);else await post('/dictionaries',dictionaryForm.value);dictionaryDialog.value=false;await select('dictionaries');ElMessage.success('字典项已保存')}catch(e:any){ElMessage.error(e.message)}}
