function spatialType(){return active.value==='floorPlan'?'FLOOR_PLAN':'BIM_MODEL'}
function spatialName(){return active.value==='floorPlan'?'平面场布图':'BIM模型'}
function fullFileUrl(url:string){if(!url)return '';return url.startsWith('http')||url.startsWith('data:')?url:`${location.origin}${url}`}
function isGlbAsset(asset:any){const name=String(asset?.fileName||asset?.fileUrl||'').toLowerCase();return name.endsWith('.glb')||name.endsWith('.gltf')}
function pointColor(type:string){return type==='TOWER_CRANE'?'#247eff':type==='HOIST'?'#8c63e9':type==='DUST_NOISE'?'#f1a33c':'#16b383'}
async function loadSpatial(){spatialAssets.value=(await get(`/spatial-assets?projectId=${scope.value.id}&type=${spatialType()}`)).sort((a:any,b:any)=>(b.id||0)-(a.id||0));spatialAsset.value=active.value==='bimModel'?(spatialAssets.value.find(isGlbAsset)||spatialAssets.value[0]||null):(spatialAssets.value[0]||null);spatialOptions.value=await get(`/spatial-point-options?projectId=${scope.value.id}`);spatialPoints.value=spatialAsset.value?await get(`/spatial-assets/${spatialAsset.value.id}/points`):[];await refreshBimViewer()}
async function chooseSpatialAsset(row:any){spatialAsset.value=row;spatialPoints.value=await get(`/spatial-assets/${row.id}/points`);await refreshBimViewer()}
function openSpatialAsset(row?:any){editingSpatialAsset.value=!!row;spatialAssetForm.value=row?{...row}:{projectId:scope.value.id,assetType:spatialType(),name:spatialName()};spatialAssetDialog.value=true}
async function uploadSpatialFile(event:any){const file=event.target.files?.[0];event.target.value='';if(!file)return;try{const fd=new FormData();fd.append('file',file);fd.append('projectId',String(scope.value.id));const r:any=await api.post('/spatial-assets/upload',fd,{timeout:60000,headers:{'Content-Type':'multipart/form-data'}});spatialAssetForm.value={...spatialAssetForm.value,fileResourceId:r.id,fileUrl:r.url,fileName:r.originalName,contentType:r.contentType};if(!spatialAssetForm.value.name)spatialAssetForm.value.name=file.name;ElMessage.success('文件已上传')}catch(e:any){ElMessage.error(e.message)}}
async function saveSpatialAsset(){try{if(editingSpatialAsset.value)await put(`/spatial-assets/${spatialAssetForm.value.id}`,spatialAssetForm.value);else await post('/spatial-assets',spatialAssetForm.value);spatialAssetDialog.value=false;await loadSpatial();ElMessage.success(editingSpatialAsset.value?'资源已更新':'资源已上传')}catch(e:any){ElMessage.error(e.message)}}
