function openSpatialPoint(row?:any){if(!spatialAsset.value)return ElMessage.warning(`请先上传${spatialName()}`);editingSpatialPoint.value=!!row;spatialPointForm.value=row?{...row}:{assetId:spatialAsset.value.id,pointType:'TOWER_CRANE',status:'ACTIVE',bindingMode:active.value==='bimModel'?'BIM_COMPONENT':'SCREEN_COORDINATE',xPercent:active.value==='bimModel'?null:50,yPercent:active.value==='bimModel'?null:50};spatialPointDialog.value=true}
function beginBimComponentSelection(){spatialPointDialog.value=false;spatialPointSelecting.value=true;ElMessage.info('请在 BIM 模型中点击需要挂载监控点的构件')}
