async function saveSpatialPoint(){try{const device=spatialOptions.value.find((x:any)=>x.type===spatialPointForm.value.pointType&&x.id===spatialPointForm.value.businessDeviceId);const payload={...spatialPointForm.value,title:spatialPointForm.value.title||device?.name};if(editingSpatialPoint.value)await put(`/spatial-points/${payload.id}`,payload);else await post('/spatial-points',payload);spatialPointDialog.value=false;await chooseSpatialAsset(spatialAsset.value);ElMessage.success(editingSpatialPoint.value?'监控点已更新':'监控点已标注')}catch(e:any){ElMessage.error(e.message)}}
