async function refreshBimViewer(){await nextTick();if(active.value!=='bimModel'||!isGlbAsset(spatialAsset.value)){disposeBimViewer();return}renderBimModel()}
function disposeBimViewer(){if(bimCleanup){bimCleanup();bimCleanup=null}if(bimViewerEl.value)bimViewerEl.value.innerHTML=''}
function bimComponentKey(object:any,root:any){const path:string[]=[];let current:any=object;while(current&&current!==root){const parent=current.parent;path.unshift(`${current.name||current.type}[${parent?parent.children.indexOf(current):0}]`);current=parent}return path.join('/')}
function spatialMarkerStyle(point:any){if(active.value!=='bimModel'||point.bindingMode!=='BIM_COMPONENT')return {left:`${point.xPercent||50}%`,top:`${point.yPercent||50}%`,background:pointColor(point.pointType)};const position=bimMarkerPositions.value[point.id];return {left:`${position?.x??-20}%`,top:`${position?.y??-20}%`,background:pointColor(point.pointType),display:position?.visible?'block':'none'}}
async function renderBimModel(){
 const el=bimViewerEl.value;if(!el||!spatialAsset.value)return;disposeBimViewer();bimLoading.value=true;bimError.value=''
 try{
  const width=el.clientWidth||800,height=el.clientHeight||520,scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(45,width/height,.01,1000),renderer=new THREE.WebGLRenderer({antialias:true})
  scene.background=new THREE.Color(0x0f1724);renderer.setPixelRatio(Math.min(window.devicePixelRatio,2));renderer.setSize(width,height);el.appendChild(renderer.domElement)
  scene.add(new THREE.HemisphereLight(0xffffff,0x334455,1.8));const sun=new THREE.DirectionalLight(0xffffff,2.2);sun.position.set(8,12,10);scene.add(sun);scene.add(new THREE.GridHelper(20,20,0x2f8cff,0x223044))
  const controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.target.set(0,0,0)
  const gltf=await new GLTFLoader().loadAsync(fullFileUrl(spatialAsset.value.fileUrl)),model=gltf.scene,componentMap=new Map<string,any>()
  model.traverse((object:any)=>{if(object.isMesh){const key=bimComponentKey(object,model);object.userData.componentKey=key;object.userData.componentName=object.name||'未命名构件';componentMap.set(key,object)}});scene.add(model)
  const box=new THREE.Box3().setFromObject(model),size=box.getSize(new THREE.Vector3()),center=box.getCenter(new THREE.Vector3()),maxDim=Math.max(size.x,size.y,size.z)||1,scale=8/maxDim
  // Translation must use the same scale as geometry, otherwise large-coordinate BIM files are moved outside the camera frustum.
  model.scale.setScalar(scale);model.position.copy(center).multiplyScalar(-scale);model.updateMatrixWorld(true)
  const fittedSize=Math.max(size.x,size.y,size.z)*scale;camera.position.set(fittedSize*1.2,fittedSize*.9,fittedSize*1.4);camera.lookAt(0,0,0);controls.update()
  const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2()
  const selectComponent=(event:MouseEvent)=>{if(!spatialPointSelecting.value)return;const rect=renderer.domElement.getBoundingClientRect();pointer.x=((event.clientX-rect.left)/rect.width)*2-1;pointer.y=-((event.clientY-rect.top)/rect.height)*2+1;raycaster.setFromCamera(pointer,camera);const hit=raycaster.intersectObject(model,true)[0];if(!hit)return;const target:any=hit.object,anchor=model.worldToLocal(hit.point.clone());spatialPointForm.value={...spatialPointForm.value,bindingMode:'BIM_COMPONENT',componentKey:target.userData.componentKey,componentName:target.userData.componentName,anchorX:Number(anchor.x.toFixed(6)),anchorY:Number(anchor.y.toFixed(6)),anchorZ:Number(anchor.z.toFixed(6)),xPercent:null,yPercent:null};spatialPointSelecting.value=false;spatialPointDialog.value=true;ElMessage.success(`已选中构件：${target.userData.componentName}`)}
  renderer.domElement.addEventListener('click',selectComponent);let stopped=false
  const updateMarkers=()=>{const next:Record<number,{x:number,y:number,visible:boolean}>={};model.updateMatrixWorld(true);for(const point of spatialPoints.value.filter((p:any)=>p.bindingMode==='BIM_COMPONENT'&&p.componentKey&&componentMap.has(p.componentKey))){const world=model.localToWorld(new THREE.Vector3(point.anchorX,point.anchorY,point.anchorZ)),projected=world.project(camera);next[point.id]={x:(projected.x+1)*50,y:(1-projected.y)*50,visible:projected.z>-1&&projected.z<1}}bimMarkerPositions.value=next}
  const resize=()=>{if(!el)return;const w=el.clientWidth||800,h=el.clientHeight||520;camera.aspect=w/h;camera.updateProjectionMatrix();renderer.setSize(w,h)};window.addEventListener('resize',resize)
  const animate=()=>{if(stopped)return;controls.update();updateMarkers();renderer.render(scene,camera);requestAnimationFrame(animate)};animate()
  bimCleanup=()=>{stopped=true;window.removeEventListener('resize',resize);renderer.domElement.removeEventListener('click',selectComponent);controls.dispose();renderer.dispose();scene.traverse((o:any)=>{if(o.geometry)o.geometry.dispose?.();if(o.material){const mats=Array.isArray(o.material)?o.material:[o.material];mats.forEach((m:any)=>m.dispose?.())}});el.innerHTML=''}
 }catch(e:any){bimError.value=e.message||'模型加载失败'}finally{bimLoading.value=false}
}
async function loadOpenAccess(){[openApiClients.value,pendingDevices.value,openApiLogs.value,rawAttendance.value,projectAreas.value]=await Promise.all([get('/open-api/clients'),get('/devices/pending'),get('/device-open-api/logs'),get('/device-open-api/raw-attendance'),get(`/project-areas?projectId=${scope.value.id}`)])}
function openOpenClient(row?:any){editingOpenClient.value=!!row;openClientForm.value=row?{...row}:{apiKey:'',apiSecret:'',vendorName:'',status:'ACTIVE'};openClientDialog.value=true}
async function saveOpenClient(){try{if(editingOpenClient.value)await put(`/open-api/clients/${openClientForm.value.id}`,openClientForm.value);else await post('/open-api/clients',openClientForm.value);openClientDialog.value=false;await loadOpenAccess();ElMessage.success(editingOpenClient.value?'接入账号已更新':'接入账号已创建')}catch(e:any){ElMessage.error(e.message)}}
async function toggleOpenClient(row:any){try{await post(`/open-api/clients/${row.id}/toggle-status`);await loadOpenAccess();ElMessage.success('接入账号状态已更新')}catch(e:any){ElMessage.error(e.message)}}
async function openConfirmDevice(row:any){if(!projectAreas.value.length)projectAreas.value=await get(`/project-areas?projectId=${scope.value.id}`);confirmDeviceForm.value={id:row.id,projectId:scope.value.id,areaId:row.areaId,deviceName:row.deviceName,vendorName:row.vendorName,deviceModel:row.deviceModel};deviceConfirmDialog.value=true}
async function confirmDevice(){try{await post(`/devices/${confirmDeviceForm.value.id}/confirm`,confirmDeviceForm.value);deviceConfirmDialog.value=false;await loadOpenAccess();ElMessage.success('设备已确认并绑定项目区域')}catch(e:any){ElMessage.error(e.message)}}
async function showJson(title:string,value:any){await ElMessageBox.alert(`<pre style="white-space:pre-wrap;text-align:left;max-height:420px;overflow:auto">${escapeHtml(typeof value==='string'?value:JSON.stringify(value,null,2))}</pre>`,title,{dangerouslyUseHTMLString:true,customClass:'json-alert',confirmButtonText:'关闭'})}
function escapeHtml(value:string){const map:Record<string,string>={'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'};return value.replace(/[&<>"']/g,s=>map[s])}
async function verifyTraining(){try{trainingIdentity.value=await post(`/mobile/training/${trainingToken}/verify`,trainingVerify.value);trainingAnswers.value=Object.fromEntries(trainingIdentity.value.questions.filter((q:any)=>q.questionType==='多选').map((q:any)=>[q.id,[]]))}catch(e:any){ElMessage.error(e.message)}}
async function submitTraining(){try{trainingResult.value=await post(`/mobile/training/${trainingToken}/submit`,{workerId:trainingIdentity.value.workerId,answers:trainingAnswers.value})}catch(e:any){ElMessage.error(e.message)}}
function logout(){session.logout();logged.value=false}
onMounted(async()=>{if(h5Entry||h5Verify)return;if(trainingToken){try{trainingPage.value=await get(`/mobile/training/${trainingToken}`)}catch(e:any){ElMessage.error(e.message)};return}if(mobileToken){try{mobileWorker.value=await get(`/mobile/worker/${mobileToken}`)}catch(e:any){ElMessage.error(e.message)};return}if(screenProjectId){const refresh=async()=>screenData.value=await get(`/screen/project/${screenProjectId}`);await refresh();window.setInterval(refresh,30000);return}window.addEventListener('popstate',()=>restoreFromUrl());if(logged.value){await loadScopeOptions();if(!await restoreFromUrl())await select(scope.value.type==='platform'?'platformDashboard':scope.value.type==='company'?'companyDashboard':'dashboard')}})
watch(()=>[active.value,spatialAsset.value?.id],()=>refreshBimViewer())
onBeforeUnmount(()=>disposeBimViewer())
</script>

<template>
<ProjectScreen v-if="screenProjectId" :data="screenData"/>
<div v-else-if="h5Entry" class="h5-entry"><div class="h5-entry-brand"><span class="brand-mark">BG</span><div><b>BuildGuard 现场入员</b><small>项目管理员 / 班组长专用</small></div></div><div v-if="!h5Logged" class="h5-entry-card"><h2>身份验证</h2><p>仅项目管理员和已启用 H5 权限的班组长可以登录。</p><el-form label-position="top" size="large"><el-form-item required label="手机号 / 登录账号"><el-input v-model="h5LoginForm.username" inputmode="tel"/></el-form-item><el-form-item required label="密码"><el-input v-model="h5LoginForm.password" type="password" show-password @keyup.enter="h5Login"/></el-form-item><el-button type="primary" @click="h5Login">登录并开始入员</el-button></el-form></div><div v-else class="h5-entry-card"><div class="h5-user"><div class="avatar">{{h5User.name?.slice(0,1)}}</div><div><b>{{h5User.name}}</b><small>{{h5User.actorType==='TEAM_LEADER'?'班组长，只能新增本班组人员':'项目管理员'}}</small></div></div><div class="h5-photo-grid"><label class="h5-photo required-photo"><img v-if="h5Worker.idCardPhotoUrl" :src="h5Worker.idCardPhotoUrl"/><span v-else>身份证正面</span><input type="file" accept="image/*" capture="environment" @change="h5Ocr"/></label><label class="h5-photo required-photo"><img v-if="h5Worker.idCardBackPhotoUrl" :src="h5Worker.idCardBackPhotoUrl"/><span v-else>身份证反面</span><input type="file" accept="image/*" capture="environment" @change="readH5Photo($event,'idCardBackPhotoUrl')"/></label><label class="h5-photo face required-photo"><img v-if="h5Worker.avatarUrl" :src="h5Worker.avatarUrl"/><span v-else>人脸照片</span><input type="file" accept="image/*" capture="environment" @change="readH5Photo($event,'avatarUrl')"/></label></div><el-form label-position="top"><el-form-item required label="所属项目"><el-select v-model="h5Worker.projectId" placeholder="请选择" :disabled="h5User.actorType==='TEAM_LEADER'" @change="h5ProjectChanged"><el-option v-for="p in h5Options.projects" :key="p.id" :label="p.projectName" :value="p.id"/></el-select></el-form-item><el-form-item required label="所属班组"><el-select v-model="h5Worker.teamId" placeholder="请选择" :disabled="h5User.actorType==='TEAM_LEADER'"><el-option v-for="t in h5Options.teams.filter((x:any)=>x.projectId===h5Worker.projectId)" :key="t.id" :label="t.teamName" :value="t.id"/></el-select></el-form-item><el-form-item required label="姓名"><el-input v-model="h5Worker.name"/></el-form-item><el-form-item required label="身份证号"><el-input v-model="h5Worker.idCardNo"/></el-form-item><el-form-item required label="手机号"><el-input v-model="h5Worker.phone" inputmode="tel"/></el-form-item><el-form-item required label="工种"><el-select v-model="h5Worker.workType" placeholder="请选择" filterable allow-create><el-option v-for="w in h5Options.workTypes" :key="w.id" :label="w.name" :value="w.name"/></el-select></el-form-item><el-button type="primary" size="large" :disabled="!h5Worker.name||!h5Worker.idCardNo||!h5Worker.phone||!h5Worker.idCardPhotoUrl||!h5Worker.idCardBackPhotoUrl||!h5Worker.avatarUrl||!h5Worker.teamId" @click="h5Submit">保存人员并自动下发设备</el-button></el-form></div></div>
<div v-else-if="h5Verify" class="h5-entry"><div class="h5-entry-brand"><span class="brand-mark">BG</span><div><b>BuildGuard 现场核验</b><small>项目管理员专用</small></div></div><div v-if="!verifyLogged" class="h5-entry-card"><h2>身份验证</h2><p>登录后可根据人员编号、身份证号、手机号或二维码 Token 核验现场人员状态。</p><el-form label-position="top" size="large"><el-form-item required label="手机号 / 登录账号"><el-input v-model="verifyForm.username"/></el-form-item><el-form-item required label="密码"><el-input v-model="verifyForm.password" type="password" show-password @keyup.enter="verifyLogin"/></el-form-item><el-button type="primary" @click="verifyLogin">登录现场核验</el-button></el-form></div><div v-else class="h5-entry-card"><div class="h5-user"><div class="avatar">{{verifyUser.name?.slice(0,1)}}</div><div><b>{{verifyUser.name}}</b><small>项目管理员</small></div></div><el-form label-position="top"><el-form-item required label="核验项目"><el-select v-model="verifyProjectId" placeholder="请选择"><el-option v-for="p in verifyUser.projects" :key="p.id" :label="p.projectName" :value="p.id"/></el-select></el-form-item><el-form-item required label="人员编号 / 身份证号 / 手机号 / 二维码 Token"><el-input v-model="verifyKeyword" @keyup.enter="verifyWorker"/></el-form-item><el-button type="primary" :disabled="!verifyProjectId||!verifyKeyword" @click="verifyWorker">开始核验</el-button></el-form><div v-if="verifyResult" class="verify-result"><div class="verify-person"><img v-if="verifyResult.avatarUrl" :src="verifyResult.avatarUrl"/><div v-else class="avatar big">人</div><div><h2>{{verifyResult.name}}</h2><p>{{verifyResult.personCode}} · {{verifyResult.workType||'未配置工种'}}</p></div></div><el-descriptions :column="1" border><el-descriptions-item label="所属单位 / 班组">{{verifyResult.unitName}} / {{verifyResult.teamName}}</el-descriptions-item><el-descriptions-item label="人员状态"><el-tag :type="tag(verifyResult.status)[1]">{{tag(verifyResult.status)[0]}}</el-tag></el-descriptions-item><el-descriptions-item label="安全教育"><el-tag :type="tag(verifyResult.safetyEducationStatus)[1]">{{tag(verifyResult.safetyEducationStatus)[0]}}</el-tag></el-descriptions-item><el-descriptions-item label="门禁状态"><el-tag :type="tag(verifyResult.accessStatus)[1]">{{tag(verifyResult.accessStatus)[0]}}</el-tag></el-descriptions-item><el-descriptions-item label="允许区域">{{verifyResult.allowedAreas?.join('、')||'未配置'}}</el-descriptions-item><el-descriptions-item label="最近考勤">{{formatDateTime(verifyResult.lastAttendanceTime)}}</el-descriptions-item></el-descriptions></div></div></div>
<div v-else-if="trainingToken" class="mobile-page training-page"><div class="mobile-brand"><span class="brand-mark">BG</span><div><b>BuildGuard 安全教育</b><small>扫码培训与考试</small></div></div><div v-if="trainingPage" class="training-card"><template v-if="trainingResult"><el-result :icon="trainingResult.passed?'success':'warning'" :title="trainingResult.passed?'考试通过':'考试未通过'" :sub-title="`得分 ${trainingResult.score}，通过分数 ${trainingResult.passScore}`"/></template><template v-else-if="trainingIdentity"><h2>{{trainingPage.taskName}}</h2><p>{{trainingIdentity.workerName}}，请完成以下考题</p><div v-for="(q,index) in trainingIdentity.questions" :key="q.id" class="question-card"><b>{{index+1}}. {{q.questionContent}}（{{q.score}} 分）</b><el-checkbox-group v-if="q.questionType==='多选'" v-model="trainingAnswers[q.id]"><el-checkbox v-for="option in questionOptions(q.options)" :key="option" :value="option.slice(0,1)" :label="option.slice(0,1)">{{option}}</el-checkbox></el-checkbox-group><el-radio-group v-else-if="questionOptions(q.options).length" v-model="trainingAnswers[q.id]"><el-radio v-for="option in questionOptions(q.options)" :key="option" :value="option.slice(0,1)">{{option}}</el-radio></el-radio-group><el-input v-else v-model="trainingAnswers[q.id]" placeholder="请输入答案"/></div><el-button type="primary" size="large" @click="submitTraining">提交考试</el-button></template><template v-else><h2>{{trainingPage.taskName}}</h2><el-tag>{{trainingPage.courseType}}</el-tag><p>{{trainingPage.courseName}}</p><div class="course-content">{{trainingPage.content||'请完成身份验证后开始本次安全教育考试。'}}</div><el-form label-position="top"><el-form-item required label="手机号"><el-input v-model="trainingVerify.phone"/></el-form-item><el-form-item required label="身份证后六位"><el-input v-model="trainingVerify.idCardSuffix" maxlength="6"/></el-form-item><el-button type="primary" size="large" @click="verifyTraining">验证身份并开始考试</el-button></el-form></template></div></div>
