   <div class="metrics"><div v-for="m in [{l:'项目总数',v:dashboard.projectCount,u:'个',c:'#247eff'},{l:'在建项目',v:dashboard.activeProjectCount,u:'个',c:'#16b383'},{l:'总工人数',v:dashboard.workerCount,u:'人',c:'#8c63e9'},{l:'今日出勤',v:dashboard.todayAttendance,u:'人',c:'#19a8b8'},{l:'安全教育通过率',v:dashboard.safetyRate,u:'%',c:'#f1a33c'},{l:'上报成功率',v:dashboard.reportRate,u:'%',c:'#ed5d5d'}]" class="metric"><span :style="{background:m.c}"></span><div><small>{{m.l}}</small><b>{{m.v}}<i>{{m.u}}</i></b></div></div></div>
   <el-card class="dashboard-section"><template #header><div class="card-head"><b>项目列表</b><el-button link type="primary" @click="select('projects')">{{canManageCompany?'管理项目':'查看项目'}}</el-button></div></template><el-table :data="dashboardProjects"><el-table-column prop="projectName" label="项目名称" min-width="220"/><el-table-column prop="projectCode" label="项目编码"/><el-table-column prop="managerName" label="负责人"/><el-table-column prop="address" label="项目地址" min-width="220"/><el-table-column prop="status" label="状态"/><el-table-column label="操作" width="100"><template #default="{row}"><el-button link type="primary" @click="enterProject(row)">进入项目</el-button></template></el-table-column></el-table></el-card>
   <el-card class="dashboard-section"><template #header><div class="card-head"><b>项目健康度统计</b><el-button link type="primary" @click="select('projectHealth')">查看全部</el-button></div></template><el-table :data="dashboardHealth"><el-table-column prop="projectName" label="项目名称" min-width="220"/><el-table-column prop="healthScore" label="健康度"/><el-table-column prop="todayAttendance" label="今日出勤"/><el-table-column prop="safetyRate" label="教育通过率"/><el-table-column label="健康状态"><template #default="{row}"><el-tag :type="row.healthStatus==='正常'?'success':row.healthStatus==='关注'?'warning':'danger'">{{row.healthStatus}}</el-tag></template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button link type="primary" @click="enterProject(row)">进入项目</el-button></template></el-table-column></el-table></el-card>
  </template>
  <template v-else-if="active==='dashboard'">
   <div class="banner"><div><span>项目运行总览</span><h3>下午好，平台管理员</h3><p>今日项目运行平稳，设备在线率良好。当前有 <b>{{dashboard.abnormalCount}}</b> 条异常考勤待处理。</p></div><div class="banner-time"><b>{{new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric'})}}</b><span>安全生产第 168 天</span></div></div>
   <div class="metrics"><div v-for="m in [{l:'项目总人数',v:dashboard.workerCount,u:'人',c:'#247eff'},{l:'今日出勤',v:dashboard.todayAttendance,u:'人次',c:'#16b383'},{l:'当前在场',v:dashboard.onSiteCount,u:'人',c:'#8c63e9'},{l:'安全教育通过率',v:dashboard.safetyRate,u:'%',c:'#19a8b8'},{l:'设备在线数',v:dashboard.onlineDevices,u:'台',c:'#f1a33c'},{l:'异常考勤',v:dashboard.abnormalCount,u:'条',c:'#ed5d5d'}]" class="metric"><span :style="{background:m.c}"></span><div><small>{{m.l}}</small><b>{{m.v}}<i>{{m.u}}</i></b></div></div></div>
   <div class="charts"><el-card><template #header><b>近 7 日出勤趋势</b></template><div id="trend" class="chart"></div></el-card><el-card><template #header><b>工种分布</b></template><div id="pie" class="chart"></div></el-card></div>
   <el-card v-if="todos.length" class="dashboard-section"><template #header><b>待办事项</b></template><div class="todo-grid"><button v-for="todo in todos" :key="todo.target" class="todo-card" @click="select(todo.target)"><b>{{todo.count}}</b><div><strong>{{todo.title}}</strong><span>{{todo.description}}</span></div></button></div></el-card>
   <el-card><template #header><div class="card-head"><b>实时考勤动态</b><el-button link type="primary" @click="select('attendance')">查看全部</el-button></div></template><el-table :data="rows.slice(0,6)"><el-table-column prop="workerName" label="人员"/><el-table-column prop="areaName" label="区域"/><el-table-column prop="deviceName" label="设备"/><el-table-column prop="attendanceTime" label="考勤时间"/><el-table-column label="结果"><template #default="{row}"><el-tag :type="tag(row.accessResult)[1]">{{tag(row.accessResult)[0]}}</el-tag></template></el-table-column></el-table></el-card>
  </template>
  <template v-else-if="active==='projectSettings'"><el-card v-loading="projectConfigLoading"><template #header><div class="card-head"><div><b>项目配置</b><span>统一维护项目运行、人员入场和设备离线规则</span></div><el-button type="primary" @click="saveProjectConfig">保存配置</el-button></div></template><el-form label-position="top" class="config-form"><div class="form-grid"><el-form-item required label="设备离线阈值（分钟）"><el-input-number v-model="projectConfig.offlineThresholdMinutes" :min="1" :max="1440"/></el-form-item><el-form-item required label="安全教育默认有效期（天）"><el-input-number v-model="projectConfig.educationValidDays" :min="1" :max="3650"/></el-form-item><el-form-item label="H5 现场入员"><el-switch v-model="projectConfig.h5WorkerEntryEnabled" active-text="启用" inactive-text="关闭"/></el-form-item><el-form-item label="入员必须采集人脸"><el-switch v-model="projectConfig.requireFacePhoto" active-text="必须" inactive-text="可选"/></el-form-item><el-form-item label="门禁要求安全教育"><el-switch v-model="projectConfig.requireSafetyEducationForAccess" active-text="必须" inactive-text="关闭"/></el-form-item></div><el-form-item label="配置说明"><el-input v-model="projectConfig.remark" type="textarea"/></el-form-item></el-form></el-card></template>
  <template v-else-if="active==='attendanceRules'"><el-card><template #header><div class="card-head"><div><b>考勤规则</b><span>每日考勤明细将按启用的规则判定迟到、早退和加班</span></div><div class="card-actions"><el-button :icon="Refresh" @click="select('attendanceRules')">刷新</el-button><el-button type="primary" :icon="Plus" @click="openAttendanceRule()">新增规则</el-button></div></div></template><el-table :data="rows"><el-table-column prop="name" label="规则名称" min-width="180"/><el-table-column prop="workStartTime" label="上班时间"/><el-table-column prop="workEndTime" label="下班时间"/><el-table-column prop="lateGraceMinutes" label="迟到宽限（分钟）"/><el-table-column prop="earlyGraceMinutes" label="早退宽限（分钟）"/><el-table-column prop="overtimeThresholdMinutes" label="加班起算（分钟）"/><el-table-column label="跨天"><template #default="{row}"><el-tag :type="row.crossDay?'warning':'info'">{{row.crossDay?'跨天班次':'当日班次'}}</el-tag></template></el-table-column><el-table-column label="状态"><template #default="{row}"><el-tag :type="tag(row.status)[1]">{{tag(row.status)[0]}}</el-tag></template></el-table-column><el-table-column label="操作" width="150"><template #default="{row}"><el-button link type="primary" @click="openAttendanceRule(row)">编辑</el-button><el-button link type="danger" @click="deleteAttendanceRule(row)">删除</el-button></template></el-table-column></el-table></el-card></template>
  <template v-else-if="active==='dictionaries'"><el-card><template #header><div class="card-head"><div><b>数据字典</b><span>统一维护平台各模块的可选项，工种字典继续在独立入口维护</span></div><div class="card-actions"><el-select v-model="dictionaryType" style="width:180px" @change="select('dictionaries',false)"><el-option label="参建单位类型" value="UNIT_TYPE"/><el-option label="设备类型" value="DEVICE_TYPE"/><el-option label="区域类型" value="AREA_TYPE"/><el-option label="班组类型" value="TEAM_TYPE"/><el-option label="教育类型" value="EDUCATION_TYPE"/><el-option label="考勤异常原因" value="ATTENDANCE_ABNORMAL"/><el-option label="上报失败原因" value="REPORT_FAILURE"/><el-option label="告警类型" value="ALARM_TYPE"/></el-select><el-button :icon="Refresh" @click="select('dictionaries')">刷新</el-button><el-button type="primary" :icon="Plus" @click="openDictionary()">新增字典项</el-button></div></div></template><el-table :data="rows"><el-table-column prop="code" label="编码"/><el-table-column prop="name" label="名称"/><el-table-column prop="sortOrder" label="排序"/><el-table-column prop="remark" label="说明" min-width="200"/><el-table-column label="状态"><template #default="{row}"><el-tag :type="tag(row.status)[1]">{{tag(row.status)[0]}}</el-tag></template></el-table-column><el-table-column label="操作" width="150"><template #default="{row}"><el-button link type="primary" @click="openDictionary(row)">编辑</el-button><el-button link type="danger" @click="deleteDictionary(row)">删除</el-button></template></el-table-column></el-table></el-card></template>
  <template v-else-if="active==='idcard'"><el-card class="id-card"><div class="scanner"><el-icon><Connection/></el-icon></div><h2>身份证读卡器</h2><p>连接华视 CVR-100U / 精伦 iDR210 本地读卡助手，读取实名信息</p><el-button type="primary" size="large" @click="mockCard">模拟读取身份证</el-button><div v-if="newWorker.name" class="card-result"><div class="avatar big">证</div><div><h3>{{newWorker.name}} · {{newWorker.gender}}</h3><p>{{newWorker.idCardNo}}</p><p>{{newWorker.address}}</p></div><el-button type="primary" plain @click="dialog=true">创建人员档案</el-button></div></el-card></template>
  <template v-else-if="['companyWorkers','companyAttendance'].includes(active)"><el-card><template #header><div class="card-head"><div><b>{{title}}</b><span>按企业下属项目汇总，数据将在录入业务数据后自动展示</span></div><el-button :icon="Refresh" @click="select(active)">刷新</el-button></div></template><el-table :data="rows" height="calc(100vh - 210px)"><el-table-column prop="projectName" label="项目名称" min-width="220"/><template v-if="active==='companyWorkers'"><el-table-column prop="workerCount" label="人员总数"/><el-table-column prop="onSiteCount" label="当前在场"/><el-table-column prop="safetyRate" label="教育通过率"/><el-table-column prop="teamCount" label="班组数量"/></template><template v-else><el-table-column prop="todayAttendance" label="今日出勤"/><el-table-column prop="onSiteCount" label="当前在场"/><el-table-column prop="abnormalCount" label="异常考勤"/><el-table-column prop="attendanceRate" label="出勤率"/></template><template #empty><el-empty description="暂无汇总数据，请先创建项目并录入业务数据"/></template></el-table></el-card></template>
	  <template v-else-if="active==='permissions'"><el-card><template #header><div class="card-head"><div><b>区域权限</b><span>按人员配置允许进入区域，保存后可下发对应区域设备</span></div><div class="card-actions"><el-button :icon="Refresh" @click="select('permissions')">刷新</el-button><el-button type="primary" :icon="Plus" @click="openPermission()">配置区域权限</el-button></div></div></template><el-table :data="projectWorkers" height="calc(100vh - 210px)"><el-table-column prop="personCode" label="人员编号" width="190"/><el-table-column prop="name" label="姓名"/><el-table-column prop="workType" label="工种"/><el-table-column label="允许进入区域" min-width="320"><template #default="{row}">{{permissionAreas(row.id)}}</template></el-table-column><el-table-column label="安全教育"><template #default="{row}"><el-tag :type="tag(row.safetyEducationStatus)[1]">{{tag(row.safetyEducationStatus)[0]}}</el-tag></template></el-table-column><el-table-column label="门禁状态"><template #default="{row}"><el-tag :type="tag(row.accessStatus)[1]">{{tag(row.accessStatus)[0]}}</el-tag></template></el-table-column><el-table-column label="操作" width="210"><template #default="{row}"><el-button link type="primary" @click="openPermission(row)">配置区域</el-button><el-button link type="success" @click="syncWorker(row)">下发设备</el-button></template></el-table-column></el-table></el-card></template>
	  <template v-else-if="active==='dailyAttendance'"><div class="daily-attendance-head"><div><h2>每日考勤明细</h2><p>按人员汇总当天每个班次的上下班打卡时间与实际出勤时长</p></div><div class="daily-filters"><el-date-picker v-model="dailyAttendanceDate" value-format="YYYY-MM-DD" placeholder="选择日期" @change="loadDailyAttendance"/><el-select v-model="dailyAttendanceTeam" clearable placeholder="全部班组"><el-option v-for="team in dailyAttendanceTeams" :key="team" :label="team" :value="team"/></el-select><el-select v-model="dailyAttendanceResult" clearable placeholder="全部出勤结果"><el-option v-for="s in ['NORMAL','MISSING','ABNORMAL','ABSENT']" :key="s" :label="tag(s)[0]" :value="s"/></el-select><el-button :icon="Refresh" @click="loadDailyAttendance">刷新</el-button></div></div><div class="daily-summary"><div v-for="m in [{l:'在册人员',v:dailyAttendance.workerCount,c:'#247eff'},{l:'出勤人数',v:dailyAttendance.attendanceCount,c:'#16b383'},{l:'正常出勤',v:dailyAttendance.normalCount,c:'#36b37e'},{l:'缺卡人数',v:dailyAttendance.missingCount,c:'#f1a33c'},{l:'异常人数',v:dailyAttendance.abnormalCount,c:'#ed5d5d'},{l:'未出勤人数',v:dailyAttendance.absentCount,c:'#9aa5b1'}]" :key="m.l"><i :style="{background:m.c}"></i><span>{{m.l}}</span><b>{{m.v||0}}<small>人</small></b></div></div><el-card class="daily-table-card"><el-table :data="dailyAttendanceRows" height="calc(100vh - 335px)"><el-table-column prop="workerName" label="姓名" fixed width="100"/><el-table-column prop="personCode" label="人员编号" width="190"/><el-table-column prop="unitName" label="参建单位" min-width="180"/><el-table-column prop="teamName" label="班组" width="140"/><el-table-column prop="workType" label="工种" width="110"/><el-table-column label="各班次打卡明细" min-width="500"><template #default="{row}"><div v-if="row.shifts.length" class="shift-list"><div v-for="(shift,index) in row.shifts" :key="index" :class="['shift-item',{missing:shift.missing}]"><b>第 {{index+1}} 班次</b><span><i>上班</i>{{shift.checkIn?formatDateTime(shift.checkIn).slice(11):'缺卡'}}</span><em>→</em><span><i>下班</i>{{shift.checkOut?formatDateTime(shift.checkOut).slice(11):'缺卡'}}</span><strong>{{shift.missing?'时长待核验':shift.duration}}</strong></div></div><span v-else class="no-attendance">当日无有效打卡</span></template></el-table-column><el-table-column prop="recordCount" label="打卡次数" width="90" align="center"/><el-table-column prop="totalDuration" label="总出勤时长" width="130"/><el-table-column label="出勤结果" fixed="right" width="110"><template #default="{row}"><el-tag :type="tag(row.result)[1]">{{tag(row.result)[0]}}</el-tag></template></el-table-column></el-table></el-card></template>
	  <template v-else-if="active==='attendanceStat'"><div v-if="!attendanceStats.trend" class="empty-feature"><el-icon><DataBoard/></el-icon><h2>考勤统计</h2><p>统计今日考勤、异常原因和近 7 日趋势。</p><el-button type="primary" @click="loadAttendanceStats">加载考勤统计</el-button></div><template v-else><div class="card-head stat-head"><div><b>考勤统计</b><span>统计口径：当前项目今日考勤记录</span></div><el-button :icon="Refresh" @click="loadAttendanceStats">刷新</el-button></div><div class="metrics attendance-metrics"><div v-for="m in [{l:'今日出勤人数',v:attendanceStats.todayAttendance,u:'人',c:'#247eff'},{l:'当前在场人数',v:attendanceStats.onSiteCount,u:'人',c:'#16b383'},{l:'今日进场次数',v:attendanceStats.inCount,u:'次',c:'#8c63e9'},{l:'今日出场次数',v:attendanceStats.outCount,u:'次',c:'#19a8b8'},{l:'正常考勤',v:attendanceStats.allowCount,u:'条',c:'#36b37e'},{l:'异常考勤',v:attendanceStats.abnormalCount,u:'条',c:'#ed5d5d'}]" class="metric"><span :style="{background:m.c}"></span><div><small>{{m.l}}</small><b>{{m.v}}<i>{{m.u}}</i></b></div></div></div><div class="stat-grid"><el-card><template #header><b>近 7 日考勤趋势</b></template><el-table :data="attendanceStats.trend"><el-table-column prop="date" label="日期"/><el-table-column prop="attendanceCount" label="出勤人数"/><el-table-column prop="recordCount" label="考勤次数"/><el-table-column prop="abnormalCount" label="异常次数"/></el-table></el-card><el-card><template #header><b>今日区域统计</b></template><el-table :data="attendanceStats.areaStats"><el-table-column prop="name" label="区域"/><el-table-column prop="count" label="考勤次数"/></el-table></el-card><el-card><template #header><b>异常原因统计</b></template><el-table :data="attendanceStats.abnormalReasonStats"><el-table-column prop="name" label="异常原因"/><el-table-column prop="count" label="次数"/></el-table></el-card></div></template></template>
	  <template v-else-if="['mockDevice','workerReports','attendanceReports'].includes(active)"><el-card><template #header><div class="card-head"><div><b>{{title}}</b><span>{{active==='mockDevice'?'模拟设备连接并生成符合规则的考勤':'使用 Mock 适配器模拟监管平台数据上报'}}</span></div><div class="card-actions"><el-button :icon="Refresh" @click="select(active)">刷新</el-button><el-button v-if="active==='mockDevice'" type="primary" @click="mockAttendance">生成今日模拟考勤</el-button><el-button v-if="active==='workerReports'" type="primary" @click="act('/gov/submit/workers','人员模拟上报完成')">模拟人员上报</el-button><el-button v-if="active==='attendanceReports'" type="primary" @click="act('/gov/submit/attendance','考勤模拟上报完成')">模拟考勤上报</el-button></div></div></template><div class="empty-feature"><el-icon><DataBoard/></el-icon><h2>{{title}}</h2><p>{{active==='mockDevice'?'选择操作按钮生成符合安全教育和区域权限规则的考勤。':'点击上方操作按钮模拟监管平台数据上报。'}}</p></div></el-card></template>
  <template v-else-if="active==='workTypes'"><el-card><template #header><div class="card-head"><div><b>工种字典</b><span>平台统一维护劳务人员可选工种</span></div><div class="card-actions"><el-button :icon="Refresh" @click="select('workTypes')">刷新</el-button><el-button type="primary" :icon="Plus" @click="openWorkType()">新增工种</el-button></div></div></template><el-table :data="filtered" height="calc(100vh - 210px)"><el-table-column prop="code" label="工种编码"/><el-table-column prop="name" label="工种名称"/><el-table-column prop="category" label="工种分类"/><el-table-column prop="sortOrder" label="排序"/><el-table-column label="状态"><template #default="{row}"><el-tag :type="tag(row.status)[1]">{{tag(row.status)[0]}}</el-tag></template></el-table-column><el-table-column label="操作" width="150" fixed="right"><template #default="{row}"><el-button link type="primary" @click="openWorkType(row)">编辑</el-button><el-button link type="danger" @click="deleteWorkType(row)">删除</el-button></template></el-table-column></el-table></el-card></template>
  <template v-else-if="['system','platformSettings'].includes(active)"><div class="empty-feature"><el-icon><Setting/></el-icon><h2>{{title}}</h2><p>{{active==='platformSettings'?'维护平台级参数、租户策略与第三方接入能力。':'当前运行于演示模式，设备与政府平台均使用适配器 Mock 实现。'}}</p></div></template>
  <template v-else-if="active==='openAccess'"><el-card><template #header><div class="card-head"><div><b>考勤设备开放接入</b><span>支持厂家通过 Signin、KeepAlive、UploadPassedLog 双发考勤数据</span></div><div class="card-actions"><el-button :icon="Refresh" @click="loadOpenAccess">刷新</el-button><el-button type="primary" :icon="Plus" @click="openOpenClient()">新增接入账号</el-button></div></div></template><el-tabs v-model="openAccessTab"><el-tab-pane label="接入账号管理" name="clients"><el-table :data="openApiClients" height="calc(100vh - 285px)"><el-table-column prop="vendorName" label="厂家名称" min-width="180"/><el-table-column prop="apiKey" label="api_key" min-width="190"/><el-table-column prop="contactName" label="联系人"/><el-table-column prop="contactPhone" label="联系电话"/><el-table-column label="状态"><template #default="{row}"><el-tag :type="tag(row.status)[1]">{{tag(row.status)[0]}}</el-tag></template></el-table-column><el-table-column label="操作" width="170" fixed="right"><template #default="{row}"><el-button link type="primary" @click="openOpenClient(row)">编辑</el-button><el-button link :type="row.status==='ACTIVE'?'danger':'success'" @click="toggleOpenClient(row)">{{row.status==='ACTIVE'?'停用':'启用'}}</el-button></template></el-table-column></el-table></el-tab-pane><el-tab-pane label="待确认设备" name="pending"><el-table :data="pendingDevices" height="calc(100vh - 285px)"><el-table-column prop="deviceName" label="设备名称" min-width="190"/><el-table-column prop="deviceNo" label="client_serial" min-width="180"/><el-table-column prop="vendorName" label="厂家"/><el-table-column prop="apiKey" label="api_key" min-width="180"/><el-table-column prop="lastSigninTime" label="最近签到" min-width="170"/><el-table-column prop="lastHeartbeatTime" label="最近心跳" min-width="170"/><el-table-column prop="lastIp" label="来源 IP"/><el-table-column label="操作" width="120" fixed="right"><template #default="{row}"><el-button link type="primary" @click="openConfirmDevice(row)">确认绑定</el-button></template></el-table-column></el-table></el-tab-pane>