  <template v-else-if="active==='towerCranes'"><div class="metrics"><div v-for="m in [{l:'塔吊数量',v:towerMonitor.craneCount||0,u:'台',c:'#247eff'},{l:'在线设备',v:towerMonitor.onlineCount||0,u:'台',c:'#16b383'},{l:'在线率',v:towerMonitor.onlineRate||0,u:'%',c:'#8c63e9'},{l:'今日吊装',v:towerMonitor.todayLiftingCount||0,u:'次',c:'#19a8b8'},{l:'今日预警',v:towerMonitor.todayAlarmCount||0,u:'条',c:'#f1a33c'},{l:'未处理预警',v:towerMonitor.unhandledAlarmCount||0,u:'条',c:'#ed5d5d'}]" class="metric"><span :style="{background:m.c}"></span><div><small>{{m.l}}</small><b>{{m.v}}<i>{{m.u}}</i></b></div></div></div><el-card><template #header><div class="card-head"><div><b>塔吊实时监测</b><span>展示当前项目塔吊实时数据、IoT在线状态和预警闭环</span></div><div class="card-actions"><el-button :icon="Refresh" @click="loadTowerMonitor">刷新</el-button><el-button type="primary" :icon="Plus" @click="openTowerCrane()">新增塔吊</el-button></div></div></template><el-table :data="rows" height="300"><el-table-column prop="craneName" label="塔吊名称" min-width="180"/><el-table-column prop="craneNo" label="塔吊编号"/><el-table-column prop="installLocation" label="安装位置"/><el-table-column label="IoT状态"><template #default="{row}"><el-tag :type="tag(row.iotDevice?.status||'UNKNOWN')[1]">{{tag(row.iotDevice?.status||'UNKNOWN')[0]}}</el-tag></template></el-table-column><el-table-column label="吊重/载荷"><template #default="{row}">{{row.latest?.loadWeight||'-'}} t / {{row.latest?.loadPercent||0}}%</template></el-table-column><el-table-column label="高度/幅度"><template #default="{row}">{{row.latest?.height||'-'}} m / {{row.latest?.amplitude||'-'}} m</template></el-table-column><el-table-column label="风速/力矩"><template #default="{row}">{{row.latest?.windSpeed||'-'}} m/s / {{row.latest?.torquePercent||0}}%</template></el-table-column><el-table-column label="状态"><template #default="{row}"><el-tag :type="tag(row.latest?.status||'UNKNOWN')[1]">{{tag(row.latest?.status||'UNKNOWN')[0]}}</el-tag></template></el-table-column><el-table-column label="操作" width="260" fixed="right"><temp