</div>
<el-drawer v-model="workerDetailDrawer" :title="`${workerDetail.worker?.name||''} · 实名制人员档案`" size="78%"><div v-if="workerDetail.worker" class="worker-detail-head"><img v-if="workerDetail.worker.avatarUrl" :src="workerDetail.worker.avatarUrl"/><div v-else class="avatar big">人</div><div><h2>{{workerDetail.worker.name}}</h2><p>{{workerDetail.worker.personCode}} · {{workerDetail.worker.workType||'未配置工种'}}</p><el-tag :type="tag(workerDetail.worker.status)[1]">{{tag(workerDetail.worker.status)[0]}}</el-tag><el-tag :type="tag(workerDetail.worker.safetyEducationStatus)[1]">{{tag(workerDetail.worker.safetyEducationStatus)[0]}}</el-tag><el-tag :type="tag(workerDetail.worker.accessStatus)[1]">{{tag(workerDetail.worker.accessStatus)[0]}}</el-tag></div></div><el-tabs v-model="workerDetailTab"><el-tab-pane label="基本信息" name="basic"><el-descriptions :column="3" border><el-descriptions-item label="姓名">{{workerDetail.worker.name}}</el-descriptions-item><el-descriptions-item label="身份证号">{{workerDetail.worker.idCardNo}}</el-descriptions-item><el-descriptions-item label="手机号">{{workerDetail.worker.phone||'-'}}</el-descriptions-item><el-descriptions-item label="性别 / 民族">{{workerDetail.worker.gender||'-'}} / {{workerDetail.worker.nation||'-'}}</el-descriptions-item><el-descriptions-item label="出生日期">{{workerDetail.worker.birthDate||'-'}}</el-descriptions-item><el-descriptions-item label="技能等级">{{workerDetail.worker.skillLevel||'-'}}</el-descriptions-item><el-descriptions-item label="地址" :span="3">{{workerDetail.worker.address||'-'}}</el-descriptions-item><el-descriptions-item label="紧急联系人">{{workerDetail.worker.emergencyContact||'-'}}</el-descriptions-item><el-descriptions-item label="紧急电话">{{workerDetail.worker.emergencyPhone||'-'}}</el-descriptions-item><el-descriptions-item label="H5入员权限"><el-tag :type="workerDetail.worker.teamLeader?'success':'info'">{{workerDetail.worker.teamLeader?'已开启':'未开启'}}</el-tag><el-button link type="primary" @click="toggleTeamLeader(workerDetail.worker,!workerDetail.worker.teamLeader)">{{workerDetail.worker.teamLeader?'关闭':'开启'}}</el-button></el-descriptions-item><el-descriptions-item label="备注">{{workerDetail.worker.remark||'-'}}</el-descriptions-item></el-descriptions></el-tab-pane><el-tab-pane label="实名制资料" name="realname"><el-descriptions :column="3" border><el-descriptions-item label="人脸照片">{{workerDetail.worker.avatarUrl?'已采集，可下发设备':'未采集，禁止下发设备'}}</el-descriptions-item><el-descriptions-item label="身份证正面">{{workerDetail.worker.idCardPhotoUrl?'已采集':'未采集'}}</el-descriptions-item><el-descriptions-item label="身份证反面">{{workerDetail.worker.idCardBackPhotoUrl?'已采集':'未采集'}}</el-descriptions-item><el-descriptions-item label="实名制上报">{{tag(workerDetail.worker.realNameReportStatus)[0]}}</el-descriptions-item><el-descriptions-item label="合同状态">{{workerDetail.worker.contractStatus||'-'}}</el-descriptions-item><el-descriptions-item label="工资状态">{{workerDetail.worker.wageStatus||'-'}}</el-descriptions-item><el-descriptions-item label="银行卡号">{{workerDetail.worker.bankCardNo||'-'}}</el-descriptions-item></el-descriptions></el-tab-pane><el-tab-pane label="项目 / 单位 / 班组" name="organization"><el-descriptions :column="2" border><el-descriptions-item label="所属项目">{{workerDetail.project?.projectName||'-'}}</el-descriptions-item><el-descriptions-item label="所属参建单位">{{workerDetail.participantUnit?.unitName||'-'}}</el-descriptions-item><el-descriptions-item label="所属班组">{{workerDetail.team?.teamName||'-'}}</el-descriptions-item><el-descriptions-item label="工种">{{workerDetail.worker.workType||'-'}}</el-descriptions-item><el-descriptions-item label="入场日期">{{workerDetail.worker.entryDate||'-'}}</el-descriptions-item><el-descriptions-item label="退场日期">{{workerDetail.worker.exitDate||'-'}}</el-descriptions-item></el-descriptions></el-tab-pane><el-tab-pane label="区域权限" name="permission"><el-table :data="workerDetail.permissions"><el-table-column label="区域"><template #default="{row}">{{workerDetail.areas?.find((a:any)=>a.id===row.areaId)?.areaName||'-'}}</template></el-table-column><el-table-column prop="permissionStatus" label="权限状态"/><el-table-column prop="deviceSyncStatus" label="下发状态"/><el-table-column prop="validEndTime" label="有效期至"/></el-table></el-tab-pane><el-tab-pane label="安全教育记录" name="education"><el-table :data="workerDetail.educationLedger"><el-table-column prop="courseName" label="课程"/><el-table-column prop="educationMethod" label="方式"/><el-table-column prop="educationDate" label="教育日期"/><el-table-column prop="validEndDate" label="有效期至"/><el-table-column label="结果"><template #default="{row}"><el-tag :type="row.passed?'success':'danger'">{{row.passed?'通过':'未通过'}}</el-tag></template></el-table-column></el-table></el-tab-pane><el-tab-pane label="考勤记录" name="attendance"><el-table :data="workerDetail.attendance"><el-table-column prop="attendanceTime" label="考勤时间"/><el-table-column prop="areaName" label="区域"/><el-table-column prop="deviceName" label="设备"/><el-table-column prop="direction" label="方向"/><el-table-column prop="denyReason" label="异常原因"/></el-table></el-tab-pane><el-tab-pane label="设备下发记录" name="sync"><el-table :data="workerDetail.syncLogs"><el-table-column prop="deviceName" label="设备"/><el-table-column prop="actionType" label="动作"/><el-table-column prop="syncStatus" label="状态"/><el-table-column prop="errorMessage" label="结果"/></el-table></el-tab-pane><el-tab-pane label="上报记录" name="report"><el-table :data="workerDetail.reportLogs"><el-table-column prop="submittedAt" label="上报时间"/><el-table-column prop="status" label="状态"/><el-table-column prop="errorMessage" label="结果"/></el-table></el-tab-pane><el-tab-pane label="二维码" name="qr"><div class="empty-feature"><h3>人员现场核验二维码</h3><p>二维码扫码页仅展示脱敏后的基础信息、状态、区域权限和最近考勤。</p><el-button type="primary" @click="showQr(workerDetail.worker)">生成 / 查看二维码</el-button></div></el-tab-pane></el-tabs></el-drawer>
<el-dialog v-model="dialog" :title="editingWorker?'编辑劳务工人实名档案':'新增劳务工人实名档案'" width="880"><el-form label-position="top"><el-alert title="人脸照片用于下发人脸考勤机，未采集人脸照片的人员禁止下发设备。" type="warning" :closable="false"/><div class="worker-photo-row"><div class="photo-box required-photo"><img v-if="newWorker.avatarUrl" :src="newWorker.avatarUrl"/><span v-else>人脸照片</span><label class="upload-button"><input type="file" accept="image/*" @change="readWorkerPhoto($event,'avatarUrl')"/>上传人脸照片</label></div><div class="photo-box required-photo"><img v-if="newWorker.idCardPhotoUrl" :src="newWorker.idCardPhotoUrl"/><span v-else>身份证正面</span><label class="upload-button"><input type="file" accept="image/*" @change="readWorkerPhoto($event,'idCardPhotoUrl')"/>上传身份证正面</label></div><div class="photo-box required-photo"><img v-if="newWorker.idCardBackPhotoUrl" :src="newWorker.idCardBackPhotoUrl"/><span v-else>身份证反面</span><label class="upload-button"><input type="file" accept="image/*" @change="readWorkerPhoto($event,'idCardBackPhotoUrl')"/>上传身份证反面</label></div></div><el-divider content-position="left">基本信息</el-divider><div class="form-grid"><el-form-item required label="姓名"><el-input v-model="newWorker.name"/></el-form-item><el-form-item required label="身份证号"><el-input v-model="newWorker.idCardNo"/></el-form-item><el-form-item required label="手机号"><el-input v-model="newWorker.phone"/></el-form-item><el-form-item required label="性别"><el-select v-model="newWorker.gender"><el-option label="男" value="男"/><el-option label="女" value="女"/></el-select></el-form-item><el-form-item required label="民族"><el-input v-model="newWorker.nation"/></el-form-item><el-form-item required label="出生日期"><el-date-picker v-model="newWorker.birthDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item required label="地址"><el-input v-model="newWorker.address"/></el-form-item><el-form-item label="技能等级"><el-input v-model="newWorker.skillLevel"/></el-form-item><el-form-item required label="工种"><el-select v-model="newWorker.workType" clearable filterable placeholder="请选择平台配置的工种"><el-option v-if="newWorker.workType&&!workTypeOptions.some((x:any)=>x.name===newWorker.workType)" :label="newWorker.workType" :value="newWorker.workType"/><el-option v-for="w in workTypeOptions.filter((x:any)=>x.status==='ACTIVE')" :key="w.id" :label="w.name" :value="w.name"/></el-select></el-form-item><el-form-item required label="参建单位"><el-select v-model="newWorker.participantUnitId" clearable><el-option v-for="u in projectUnits" :key="u.id" :label="u.unitName" :value="u.id"/></el-select></el-form-item><el-form-item required label="班组"><el-select v-model="newWorker.teamId" clearable><el-option v-for="t in projectTeams.filter((x:any)=>!newWorker.participantUnitId||x.participantUnitId===newWorker.participantUnitId)" :key="t.id" :label="t.teamName" :value="t.id"/></el-select></el-form-item><el-form-item required label="人员状态"><el-select v-model="newWorker.status"><el-option label="待入场" value="WAIT_ENTRY"/><el-option label="在场" value="ON_SITE"/><el-option label="已退场" value="LEFT_SITE"/><el-option label="黑名单" value="BLACKLIST"/></el-select></el-form-item></div><el-divider content-position="left">从业与预留信息</el-divider><div class="form-grid"><el-form-item label="银行卡号（预留）"><el-input v-model="newWorker.bankCardNo"/></el-form-item><el-form-item label="合同状态"><el-select v-model="newWorker.contractStatus" clearable><el-option label="未签订" value="NOT_SIGNED"/><el-option label="已签订" value="SIGNED"/><el-option label="已到期" value="EXPIRED"/></el-select></el-form-item><el-form-item label="工资发放状态（预留）"><el-select v-model="newWorker.wageStatus" clearable><el-option label="未发放" value="NOT_PAID"/><el-option label="已发放" value="PAID"/><el-option label="异常" value="ABNORMAL"/></el-select></el-form-item><el-form-item label="紧急联系人"><el-input v-model="newWorker.emergencyContact"/></el-form-item><el-form-item label="紧急联系人电话"><el-input v-model="newWorker.emergencyPhone"/></el-form-item><el-form-item label="身份证读取"><el-button @click="mockCard">模拟读取身份证</el-button></el-form-item></div><el-form-item label="备注"><el-input v-model="newWorker.remark" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="saveWorker">保存人员档案</el-button></template></el-dialog>
<el-dialog v-model="workTypeDialog" :title="editingWorkType?'编辑工种':'新增工种'" width="620"><el-alert title="工种字典由平台统一维护，启用后的工种可在劳务人员档案中选择。" type="info" :closable="false"/><el-form label-position="top"><div class="form-grid"><el-form-item required label="工种编码"><el-input v-model="workTypeForm.code" placeholder="例如 CARPENTER"/></el-form-item><el-form-item required label="工种名称"><el-input v-model="workTypeForm.name" placeholder="例如 木工"/></el-form-item><el-form-item label="工种分类"><el-input v-model="workTypeForm.category" placeholder="例如 土建施工"/></el-form-item><el-form-item label="排序"><el-input-number v-model="workTypeForm.sortOrder" :min="0"/></el-form-item><el-form-item required label="状态"><el-select v-model="workTypeForm.status"><el-option label="正常" value="ACTIVE"/><el-option label="禁用" value="DISABLED"/></el-select></el-form-item><el-form-item label="备注"><el-input v-model="workTypeForm.remark"/></el-form-item></div></el-form><template #footer><el-button @click="workTypeDialog=false">取消</el-button><el-button type="primary" @click="saveWorkType">保存工种</el-button></template></el-dialog>
<el-dialog v-model="attendanceRuleDialog" :title="editingAttendanceRule?'编辑考勤规则':'新增考勤规则'" width="680"><el-form label-position="top"><div class="form-grid"><el-form-item required label="规则名称"><el-input v-model="attendanceRuleForm.name"/></el-form-item><el-form-item required label="状态"><el-select v-model="attendanceRuleForm.status"><el-option label="启用" value="ACTIVE"/><el-option label="停用" value="DISABLED"/></el-select></el-form-item><el-form-item required label="上班时间"><el-time-picker v-model="attendanceRuleForm.workStartTime" value-format="HH:mm" format="HH:mm"/></el-form-item><el-form-item required label="下班时间"><el-time-picker v-model="attendanceRuleForm.workEndTime" value-format="HH:mm" format="HH:mm"/></el-form-item><el-form-item label="迟到宽限（分钟）"><el-input-number v-model="attendanceRuleForm.lateGraceMinutes" :min="0" :max="180"/></el-form-item><el-form-item label="早退宽限（分钟）"><el-input-number v-model="attendanceRuleForm.earlyGraceMinutes" :min="0" :max="180"/></el-form-item><el-form-item label="加班起算（分钟）"><el-input-number v-model="attendanceRuleForm.overtimeThresholdMinutes" :min="0" :max="360"/></el-form-item><el-form-item label="跨天班次"><el-switch v-model="attendanceRuleForm.crossDay"/></el-form-item></div></el-form><template #footer><el-button @click="attendanceRuleDialog=false">取消</el-button><el-button type="primary" @click="saveAttendanceRule">保存规则</el-button></template></el-dialog>
<el-dialog v-model="dictionaryDialog" :title="editingDictionary?'编辑字典项':'新增字典项'" width="640"><el-form label-position="top"><div class="form-grid"><el-form-item required label="字典类型"><el-select v-model="dictionaryForm.dictType"><el-option label="参建单位类型" value="UNIT_TYPE"/><el-option label="设备类型" value="DEVICE_TYPE"/><el-option label="区域类型" value="AREA_TYPE"/><el-option label="班组类型" value="TEAM_TYPE"/><el-option label="教育类型" value="EDUCATION_TYPE"/><el-option label="考勤异常原因" value="ATTENDANCE_ABNORMAL"/><el-option label="上报失败原因" value="REPORT_FAILURE"/><el-option label="告警类型" value="ALARM_TYPE"/></el-select></el-form-item><el-form-item required label="编码"><el-input v-model="dictionaryForm.code"/></el-form-item><el-form-item required label="名称"><el-input v-model="dictionaryForm.name"/></el-form-item><el-form-item label="排序"><el-input-number v-model="dictionaryForm.sortOrder" :min="0"/></el-form-item><el-form-item required label="状态"><el-select v-model="dictionaryForm.status"><el-option label="启用" value="ACTIVE"/><el-option label="停用" value="DISABLED"/></el-select></el-form-item></div><el-form-item label="说明"><el-input v-model="dictionaryForm.remark" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="dictionaryDialog=false">取消</el-button><el-button type="primary" @click="saveDictionary">保存字典项</el-button></template></el-dialog>
<el-dialog v-model="importDialog" title="批量导入预览" width="900"><el-alert :title="`校验通过 ${importPreview.validCount} 条，错误 ${importPreview.errorCount} 条`" :type="importPreview.errorCount?'warning':'success'" :closable="false"/><el-table :data="importRows" max-height="430" style="margin-top:14px"><el-table-column prop="name" label="姓名"/><el-table-column prop="idCardNo" label="身份证号" min-width="190"/><el-table-column prop="workType" label="工种"/><el-table-column prop="participantUnitName" label="参建单位"/><el-table-column prop="teamName" label="班组"/><el-table-column label="校验结果" min-width="220"><template #default="{row}"><el-tag :type="row.valid?'success':'danger'">{{row.valid?'通过':row.error}}</el-tag></template></el-table-column></el-table><template #footer><el-button @click="importDialog=false">取消</el-button><el-button type="primary" :disabled="importPreview.errorCount>0||!importPreview.validCount" @click="confirmImport">确认导入</el-button></template></el-dialog>
<el-dialog v-model="courseDialog" :title="editingCourse?'编辑教育课程':'新增教育课程'" width="760"><el-form label-position="top"><div class="form-grid"><el-form-item required label="课程名称"><el-input v-model="courseForm.name"/></el-form-item><el-form-item required label="课程类型"><el-select v-model="courseForm.courseType"><el-option v-for="s in ['入场安全教育','三级安全教育','专项安全教育','班前教育','临时教育','其他']" :key="s" :label="s" :value="s"/></el-select></el-form-item><el-form-item required label="通过分数"><el-input-number v-model="courseForm.passScore" :min="0" :max="100"/></el-form-item><el-form-item required label="有效期天数"><el-input-number v-model="courseForm.validDays" :min="1"/></el-form-item></div><el-form-item required label="课程内容"><el-input v-model="courseForm.content" type="textarea" :rows="4"/></el-form-item><el-form-item required label="课程考题"><el-select v-model="courseForm.questionIds" multiple filterable collapse-tags placeholder="从当前项目考题库中选择考题"><el-option v-for="q in questionBank" :key="q.id" :label="`[${q.questionType}] ${q.questionContent}`" :value="q.id"/></el-select><small class="form-tip">课程负责组卷，考题可被多个课程重复使用。</small></el-form-item></el-form><template #footer><el-button @click="courseDialog=false">取消</el-button><el-button type="primary" @click="saveCourse">保存课程</el-button></template></el-dialog>
<el-dialog v-model="questionDialog" :title="editingQuestion?'编辑题库考题':'新增题库考题'" width="760"><el-form label-position="top"><div class="form-grid"><el-form-item required label="题型"><el-select v-model="questionForm.questionType" @change="changeQuestionType"><el-option v-for="s in ['单选','多选','判断']" :key="s" :label="s" :value="s"/></el-select></el-form-item><el-form-item required label="分值"><el-input-number v-model="questionForm.score" :min="1"/></el-form-item></div><el-form-item required label="题目内容"><el-input v-model="questionForm.questionContent" type="textarea" :rows="2"/></el-form-item><el-form-item required label="选项"><div class="question-options"><div v-for="(option,index) in questionForm.optionItems" :key="index" class="question-option"><span>{{String.fromCharCode(65+index)}}.</span><el-input v-model="questionForm.optionItems[index]" :disabled="questionForm.questionType==='判断'" :placeholder="`请输入选项 ${String.fromCharCode(65+index)}`"/><el-button v-if="questionForm.questionType!=='判断'" link type="danger" :disabled="questionForm.optionItems.length<=2" @click="removeQuestionOption(index)">删除</el-button></div><el-button v-if="questionForm.questionType!=='判断'" link type="primary" @click="addQuestionOption">+ 添加选项</el-button></div></el-form-item><el-form-item required label="正确答案"><el-select v-if="questionForm.questionType==='多选'" v-model="questionForm.answerValues" multiple placeholder="请选择全部正确选项"><el-option v-for="o in answerOptions()" :key="o.value" :label="o.label" :value="o.value"/></el-select><el-select v-else v-model="questionForm.answerValues" placeholder="请选择正确答案"><el-option v-for="o in answerOptions()" :key="o.value" :label="o.label" :value="o.value"/></el-select></el-form-item><el-form-item label="答案解析"><el-input v-model="questionForm.analysis" type="textarea" :rows="2"/></el-form-item></el-form><template #footer><el-button @click="questionDialog=false">取消</el-button><el-button type="primary" @click="saveQuestion">保存到题库</el-button></template></el-dialog>
<el-dialog v-model="ledgerDialog" title="录入线下安全教育台账" width="720"><el-form label-position="top"><div class="form-grid"><el-form-item required label="受教育人员"><el-select v-model="ledgerForm.workerId"><el-option v-for="w in projectWorkers" :key="w.id" :label="`${w.name}（${w.personCode}）`" :value="w.id"/></el-select></el-form-item><el-form-item required label="教育类型"><el-select v-model="ledgerForm.educationType"><el-option v-for="s in ['入场安全教育','三级安全教育','专项安全教育','班前教育','临时教育','其他']" :key="s" :label="s" :value="s"/></el-select></el-form-item><el-form-item required label="课程名称"><el-input v-model="ledgerForm.courseName"/></el-form-item><el-form-item required label="授课人"><el-input v-model="ledgerForm.teacher"/></el-form-item><el-form-item required label="教育日期"><el-date-picker v-model="ledgerForm.educationDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item required label="教育地点"><el-input v-model="ledgerForm.educationLocation"/></el-form-item><el-form-item required label="有效期开始"><el-date-picker v-model="ledgerForm.validStartDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item required label="有效期结束"><el-date-picker v-model="ledgerForm.validEndDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item required label="是否通过"><el-switch v-model="ledgerForm.passed" active-text="通过" inactive-text="未通过"/></el-form-item><el-form-item required label="学时"><el-input-number v-model="ledgerForm.classHours" :min="0"/></el-form-item></div></el-form><template #footer><el-button @click="ledgerDialog=false">取消</el-button><el-button type="primary" @click="saveLedger">保存台账</el-button></template></el-dialog>
<el-dialog v-model="permissionDialog" title="配置人员区域权限" width="680"><el-form label-position="top"><el-form-item required label="劳务人员"><el-select v-model="permissionForm.workerId" filterable><el-option v-for="w in projectWorkers" :key="w.id" :label="`${w.name}（${w.personCode}）`" :value="w.id"/></el-select></el-form-item><el-form-item required label="允许进入区域"><el-checkbox-group v-model="permissionForm.areaIds" class="area-checks"><el-checkbox v-for="a in projectAreas" :key="a.id" :value="a.id" :label="a.id">{{a.areaName}}（{{a.areaType}}）</el-checkbox></el-checkbox-group></el-form-item><div class="form-grid"><el-form-item required label="有效期开始"><el-date-picker v-model="permissionForm.validStartTime" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item><el-form-item required label="有效期结束"><el-date-picker v-model="permissionForm.validEndTime" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item></div><el-alert title="保存区域权限后，需要人员在场且安全教育已通过，才能下发到对应区域的设备。" type="info" :closable="false"/></el-form><template #footer><el-button @click="permissionDialog=false">取消</el-button><el-button type="primary" @click="savePermission">保存区域权限</el-button></template></el-dialog>
<el-dialog v-model="trainingTaskDialog" :title="editingTrainingTask?'编辑培训任务':'新增培训任务'" width="720"><el-alert title="培训任务可以覆盖全项目人员，也可以只指定部分班组或人员。" type="info" :closable="false"/><el-form label-position="top"><div class="form-grid"><el-form-item required label="任务名称"><el-input v-model="trainingTaskForm.name"/></el-form-item><el-form-item required label="培训课程"><el-select v-model="trainingTaskForm.courseId"><el-option v-for="c in educationCourses" :key="c.id" :label="c.name" :value="c.id"/></el-select></el-form-item><el-form-item required label="培训对象范围"><el-select v-model="trainingTaskForm.targetType" @change="trainingTaskForm.targetIds=[]"><el-option label="全项目人员" value="ALL"/><el-option label="指定班组" value="TEAM"/><el-option label="指定人员" value="WORKER"/></el-select></el-form-item><el-form-item v-if="trainingTaskForm.targetType==='TEAM'" required label="指定班组"><el-select v-model="trainingTaskForm.targetIds" multiple collapse-tags><el-option v-for="t in projectTeams" :key="t.id" :label="t.teamName" :value="t.id"/></el-select></el-form-item><el-form-item v-if="trainingTaskForm.targetType==='WORKER'" required label="指定人员"><el-select v-model="trainingTaskForm.targetIds" multiple collapse-tags filterable><el-option v-for="w in projectWorkers" :key="w.id" :label="`${w.name}（${w.personCode}）`" :value="w.id"/></el-select></el-form-item><el-form-item required label="开始时间"><el-date-picker v-model="trainingTaskForm.startTime" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item><el-form-item required label="结束时间"><el-date-picker v-model="trainingTaskForm.endTime" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item><el-form-item required label="状态"><el-select v-model="trainingTaskForm.status"><el-option label="开放" value="ACTIVE"/><el-option label="停用" value="DISABLED"/></el-select></el-form-item></div><el-form-item label="备注"><el-input v-model="trainingTaskForm.remark"/></el-form-item></el-form><template #footer><el-button @click="trainingTaskDialog=false">取消</el-button><el-button type="primary" @click="saveTrainingTask">保存培训任务</el-button></template></el-dialog>
<el-dialog v-model="deviceDialog" :title="editingDevice?'编辑考勤设备':'新增考勤设备'" width="760"><el-alert title="第一期只做轻量设备接入管理：基础信息、项目区域绑定、开放接口状态查看，不做完整设备控制。" type="info" :closable="false"/><el-form label-position="top"><div class="form-grid"><el-form-item required label="设备名称"><el-input v-model="deviceForm.deviceName"/></el-form-item><el-form-item required label="设备编号 / client_serial"><el-input v-model="deviceForm.deviceNo"/></el-form-item><el-form-item required label="绑定区域"><el-select v-model="deviceForm.areaId" clearable placeholder="请选择"><el-option v-for="a in projectAreas" :key="a.id" :label="`${a.areaName}（${a.areaType}）`" :value="a.id"/></el-select></el-form-item><el-form-item label="厂家名称"><el-input v-model="deviceForm.vendorName" placeholder="如 宇泛、海清"/></el-form-item><el-form-item label="设备型号"><el-input v-model="deviceForm.deviceModel"/></el-form-item><el-form-item required label="设备类型"><el-select v-model="deviceForm.deviceType" placeholder="请选择"><el-option label="人脸考勤机" value="人脸考勤机"/><el-option label="闸机" value="闸机"/><el-option label="门禁" value="门禁"/></el-select></el-form-item><el-form-item label="安装位置"><el-input v-model="deviceForm.location"/></el-form-item><el-form-item label="设备 IP"><el-input v-model="deviceForm.ipAddress"/></el-form-item><el-form-item required label="状态"><el-select v-model="deviceForm.status" placeholder="请选择"><el-option label="待确认" value="PENDING_CONFIRM"/><el-option label="在线" value="ONLINE"/><el-option label="离线" value="OFFLINE"/><el-option label="停用" value="DISABLED"/><el-option label="未知" value="UNKNOWN"/></el-select></el-form-item><el-form-item label="备注"><el-input v-model="deviceForm.remark"/></el-form-item></div></el-form><template #footer><el-button @click="deviceDialog=false">取消</el-button><el-button type="primary" @click="saveDevice">保存设备</el-button></template></el-dialog>
<el-dialog v-model="openClientDialog" :title="editingOpenClient?'编辑接入账号':'新增接入账号'" width="680"><el-form label-position="top"><div class="form-grid"><el-form-item required label="厂家名称"><el-input v-model="openClientForm.vendorName"/></el-form-item><el-form-item required label="api_key"><el-input v-model="openClientForm.apiKey"/></el-form-item><el-form-item required label="api_secret"><el-input v-model="openClientForm.apiSecret" show-password/></el-form-item><el-form-item label="联系人"><el-input v-model="openClientForm.contactName"/></el-form-item><el-form-item label="联系电话"><el-input v-model="openClientForm.contactPhone"/></el-form-item><el-form-item required label="状态"><el-select v-model="openClientForm.status" placeholder="请选择"><el-option label="正常" value="ACTIVE"/><el-option label="停用" value="DISABLED"/></el-select></el-form-item><el-form-item label="备注"><el-input v-model="openClientForm.remark"/></el-form-item></div></el-form><template #footer><el-button @click="openClientDialog=false">取消</el-button><el-button type="primary" @click="saveOpenClient">保存接入账号</el-button></template></el-dialog>
<el-dialog v-model="deviceConfirmDialog" title="确认待接入设备" width="680"><el-alert title="确认后，该设备后续考勤会按 client_serial 自动归属到绑定的项目和区域。" type="warning" :closable="false"/><el-form label-position="top"><div class="form-grid"><el-form-item required label="设备名称"><el-input v-model="confirmDeviceForm.deviceName"/></el-form-item><el-form-item required label="所属项目"><el-select v-model="confirmDeviceForm.projectId" disabled><el-option :label="scope.name" :value="scope.id"/></el-select></el-form-item><el-form-item required label="绑定区域"><el-select v-model="confirmDeviceForm.areaId" placeholder="请选择"><el-option v-for="a in projectAreas" :key="a.id" :label="`${a.areaName}（${a.areaType}）`" :value="a.id"/></el-select></el-form-item><el-form-item label="厂家名称"><el-input v-model="confirmDeviceForm.vendorName"/></el-form-item><el-form-item label="设备型号"><el-input v-model="confirmDeviceForm.deviceModel"/></el-form-item></div></el-form><template #footer><el-button @click="deviceConfirmDialog=false">取消</el-button><el-button type="primary" @click="confirmDevice">确认绑定</el-button></template></el-dialog>
<el-dialog v-model="qrDialog" title="培训任务二维码" width="520" class="qr-dialog"><div class="qr-content"><img :src="qrDataUrl" alt="培训任务二维码"/><p>{{qrUrl}}</p><el-alert v-if="qrLocalOnly" title="当前通过 localhost 打开系统，二维码只能在本机使用。手机扫码时，请通过本机局域网 IP 打开后台后重新生成二维码，或等待部署到服务器。" type="warning" :closable="false"/><el-alert v-else title="二维码已使用当前访问地址生成，手机与本机网络互通时可直接扫码考试。" type="success" :closable="false"/></div><template #footer><el-button @click="qrDialog=false">关闭</el-button></template></el-dialog>
<el-dialog v-model="companyDialog" :title="editingCompany?'编辑企业':'新增企业'" width="620"><el-alert title="企业由平台超级管理员统一创建和维护" type="info" :closable="false"/><el-form label-position="top"><div class="form-grid"><el-form-item required label="企业名称"><el-input v-model="newCompany.name"/></el-form-item><el-form-item required label="统一信用代码"><el-input v-model="newCompany.creditCode"/></el-form-item><el-form-item required label="企业类型"><el-input v-model="newCompany.type"/></el-form-item><el-form-item required label="联系人"><el-input v-model="newCompany.contactName"/></el-form-item><el-form-item required label="联系电话"><el-input v-model="newCompany.contactPhone"/></el-form-item></div></el-form><template #footer><el-button @click="companyDialog=false">取消</el-button><el-button type="primary" @click="saveCompany">{{editingCompany?'保存修改':'创建企业'}}</el-button></template></el-dialog>
<el-dialog v-model="projectModuleDialog" title="项目模块授权" width="560"><el-alert :title="`配置“${projectModuleForm.projectName||''}”可启用的业务模块`" type="info" :closable="false"/><el-checkbox-group v-model="projectModuleForm.enabledModules" class="module-checks"><el-checkbox v-for="m in projectFeatureOptions" :key="m[0]" :label="m[0]" :value="m[0]">{{m[1]}}</el-checkbox></el-checkbox-group><template #footer><el-button @click="projectModuleDialog=false">取消</el-button><el-button type="primary" @click="saveProjectModules">保存授权</el-button></template></el-dialog>
<el-dialog v-model="iotDeviceDialog" :title="editingIotDevice?'编辑IoT设备':'新增IoT设备'" width="760"><el-alert title="建议现场只注册 KKOS 网关，扬尘、升降机、视频AI等硬件作为网关下挂子设备接入。" type="info" :closable="false"/><el-form label-position="top"><div class="form-grid"><el-form-item required label="设备名称"><el-input v-model="iotDeviceForm.deviceName"/></el-form-item><el-form-item required label="设备编码"><el-input v-model="iotDeviceForm.deviceCode"/></el-form-item><el-form-item required label="节点类型"><el-select v-model="iotDeviceForm.nodeType" placeholder="请选择"><el-option label="KKOS网关" value="GATEWAY"/><el-option label="网关子设备" value="SUB_DEVICE"/><el-option label="直连设备" value="DIRECT_DEVICE"/></el-select></el-form-item><el-form-item label="父级网关编码"><el-input v-model="iotDeviceForm.parentDeviceCode" placeholder="子设备填写 KKOS 网关编码"/></el-form-item><el-form-item required label="设备类型"><el-select v-model="iotDeviceForm.deviceType" placeholder="请选择"><el-option label="KKOS网关" value="KKOS网关"/><el-option label="塔吊监测设备" value="塔吊监测设备"/><el-option label="扬尘噪音设备" value="扬尘噪音设备"/><el-option label="升降机监测设备" value="升降机监测设备"/><el-option label="视频AI设备" value="视频AI设备"/><el-option label="考勤设备" value="考勤设备"/><el-option label="其他设备" value="其他设备"/></el-select></el-form-item><el-form-item label="接入协议"><el-input v-model="iotDeviceForm.protocol" placeholder="HTTP/MQTT/GB28181/RTSP等"/></el-form-item><el-form-item label="厂家名称"><el-input v-model="iotDeviceForm.vendorName"/></el-form-item><el-form-item label="apiKey"><el-input v-model="iotDeviceForm.apiKey"/></el-form-item><el-form-item label="apiSecret"><el-input v-model="iotDeviceForm.apiSecret" show-password/></el-form-item><el-form-item label="绑定项目"><el-select v-model="iotDeviceForm.projectId" clearable placeholder="未绑定"><el-option v-for="p in scopeOptions.projects" :key="p.id" :label="p.projectName" :value="p.id"/></el-select></el-form-item><el-form-item required label="状态"><el-select v-model="iotDeviceForm.status" placeholder="请选择"><el-option label="在线" value="ONLINE"/><el-option label="离线" value="OFFLINE"/><el-option label="停用" value="DISABLED"/><el-option label="未知" value="UNKNOWN"/></el-select></el-form-item><el-form-item label="备注"><el-input v-model="iotDeviceForm.remark"/></el-form-item></div></el-form><template #footer><el-button @click="iotDeviceDialog=false">取消</el-button><el-button type="primary" @click="saveIotDevice">保存IoT设备</el-button></template></el-dialog>
<el-dialog v-model="towerCraneDialog" :title="editingTowerCrane?'编辑塔吊档案':'新增塔吊档案'" width="780"><el-alert title="塔吊档案绑定 IoT 设备后，实时数据和预警会自动进入当前项目塔吊监测模块。" type="info" :closable="false"/><el-form label-position="top"><div class="form-grid"><el-form-item required label="塔吊名称"><el-input v-model="towerCraneForm.craneName"/></el-form-item><el-form-item required label="塔吊编号"><el-input v-model="towerCraneForm.craneNo"/></el-form-item><el-form-item label="备案编号"><el-input v-model="towerCraneForm.recordNo"/></el-form-item><el-form-item label="绑定IoT设备"><el-select v-model="towerCraneForm.iotDeviceId" clearable filterable placeholder="请选择"><el-option v-for="d in iotDeviceOptions.filter((x:any)=>!x.projectId||x.projectId===scope.id)" :key="d.id" :label="`${d.deviceName}（${d.deviceCode}）`" :value="d.id"/></el-select></el-form-item><el-form-item label="安装位置"><el-input v-model="towerCraneForm.installLocation"/></el-form-item><el-form-item label="产权单位"><el-input v-model="towerCraneForm.propertyUnit"/></el-form-item><el-form-item label="安装单位"><el-input v-model="towerCraneForm.installUnit"/></el-form-item><el-form-item label="检测单位"><el-input v-model="towerCraneForm.inspectionUnit"/></el-form-item><el-form-item label="司机"><el-input v-model="towerCraneForm.driverName"/></el-form-item><el-form-item label="负责人"><el-input v-model="towerCraneForm.managerName"/></el-form-item><el-form-item required label="状态"><el-select v-model="towerCraneForm.status" placeholder="请选择"><el-option label="正常" value="ACTIVE"/><el-option label="停用" value="DISABLED"/></el-select></el-form-item></div><el-form-item label="备注"><el-input v-model="towerCraneForm.remark"/></el-form-item></el-form><template #footer><el-button @click="towerCraneDialog=false">取消</el-button><el-button type="primary" @click="saveTowerCrane">保存塔吊档案</el-button></template></el-dialog>
<el-dialog v-model="monitorDeviceDialog" :title="editingMonitorDevice?'编辑监测设备':'新增监测设备'" width="760"><el-alert :title="`${monitorName()}设备绑定 IoT 子设备后，数据会自动进入当前项目模块。`" type="info" :closable="false"/><el-form label-position="top"><div class="form-grid"><el-form-item required label="设备名称"><el-input v-model="monitorDeviceForm.deviceName"/></el-form-item><el-form-item required label="设备编号"><el-input v-model="monitorDeviceForm.deviceNo"/></el-form-item><el-form-item label="绑定IoT设备"><el-select v-model="monitorDeviceForm.iotDeviceId" clearable filterable placeholder="请选择"><el-option v-for="d in iotDeviceOptions.filter((x:any)=>!x.projectId||x.projectId===scope.id)" :key="d.id" :label="`${d.deviceName}（${d.deviceCode}）`" :value="d.id"/></el-select></el-form-item><el-form-item label="安装位置"><el-input v-model="monitorDeviceForm.installLocation"/></el-form-item><el-form-item label="厂家名称"><el-input v-model="monitorDeviceForm.vendorName"/></el-form-item><el-form-item label="设备型号"><el-input v-model="monitorDeviceForm.deviceModel"/></el-form-item><el-form-item required label="状态"><el-select v-model="monitorDeviceForm.status" placeholder="请选择"><el-option label="正常" value="ACTIVE"/><el-option label="停用" value="DISABLED"/></el-select></el-form-item></div><el-form-item label="备注"><el-input v-model="monitorDeviceForm.remark"/></el-form-item></el-form><template #footer><el-button @click="monitorDeviceDialog=false">取消</el-button><el-button type="primary" @click="saveMonitorDevice">保存监测设备</el-button></template></el-dialog>
<el-dialog v-model="spatialAssetDialog" :title="editingSpatialAsset?'编辑空间资源':'上传空间资源'" width="680"><el-alert :title="active==='floorPlan'?'支持上传 PNG/JPG/SVG 等平面场布图。':'支持上传 glb/gltf/ifc/rvt/zip 等 BIM 模型文件，第一版用于留存和点位叠加。'" type="info" :closable="false"/><el-form label-position="top"><div class="form-grid"><el-form-item required label="资源名称"><el-input v-model="spatialAssetForm.name"/></el-form-item><el-form-item required label="上传文件"><label class="upload-button"><input type="file" :accept="active==='floorPlan'?'image/*':'.glb,.gltf,.ifc,.rvt,.zip,.obj'" @change="uploadSpatialFile"/>选择文件</label><span class="file-hint">{{spatialAssetForm.fileName||spatialAssetForm.fileUrl||'未上传'}}</span></el-form-item></div><el-form-item label="备注"><el-input v-model="spatialAssetForm.remark" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="spatialAssetDialog=false">取消</el-button><el-button type="primary" @click="saveSpatialAsset">保存资源</el-button></template></el-dialog>
<el-dialog v-model="spatialPointDialog" :title="editingSpatialPoint?'编辑监控点':'新增监控点'" width="680"><el-alert :title="active==='bimModel'?'选择“在模型中选择构件”后点击目标构件，再选择要绑定的设备。构件会随模型旋转、缩放和刷新自动跟随。':'可先在图上点击定位，再选择绑定设备；坐标按百分比保存，适配不同屏幕尺寸。'" type="info" :closable="false"/><el-form label-position="top"><div class="form-grid"><el-form-item required label="监控点类型"><el-select v-model="spatialPointForm.pointType" placeholder="请选择" @change="spatialPointForm.businessDeviceId=null"><el-option label="塔吊监控点" value="TOWER_CRANE"/><el-option label="升降机监控点" value="HOIST"/><el-option label="扬尘噪音监测点" value="DUST_NOISE"/><el-option label="视频监控点" value="VIDEO_AI"/></el-select></el-form-item><el-form-item required label="绑定设备"><el-select v-model="spatialPointForm.businessDeviceId" filterable placeholder="请选择"><el-option v-for="d in spatialOptions.filter((x:any)=>x.type===spatialPointForm.pointType)" :key="`${d.type}-${d.id}`" :label="`${d.name}（${d.code}）`" :value="d.id"/></el-select></el-form-item><el-form-item v-if="active==='bimModel'" required label="已选 BIM 构件"><el-input :model-value="spatialPointForm.componentName||'尚未选择构件'" readonly/></el-form-item><el-form-item label="点位名称"><el-input v-model="spatialPointForm.title" placeholder="不填则使用设备名称"/></el-form-item><el-form-item required label="状态"><el-select v-model="spatialPointForm.status" placeholder="请选择"><el-option label="正常" value="ACTIVE"/><el-option label="禁用" value="DISABLED"/></el-select></el-form-item><el-form-item v-if="active!=='bimModel'" required label="X 坐标 %"><el-input-number v-model="spatialPointForm.xPercent" :min="0" :max="100" :precision="1"/></el-form-item><el-form-item v-if="active!=='bimModel'" required label="Y 坐标 %"><el-input-number v-model="spatialPointForm.yPercent" :min="0" :max="100" :precision="1"/></el-form-item></div><el-form-item label="备注"><el-input v-model="spatialPointForm.remark" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="spatialPointDialog=false">取消</el-button><el-button v-if="active==='bimModel'" @click="beginBimComponentSelection">在模型中选择构件</el-button><el-button type="primary" @click="saveSpatialPoint">保存监控点</el-button></template></el-dialog>
<el-dialog v-model="spatialPointDetailDialog" title="监控点详情" width="780"><div v-if="spatialPointDetail.point" class="point-detail"><div class="point-summary"><span :style="{background:pointColor(spatialPointDetail.point.pointType)}">{{spatialPointDetail.point.pointTypeName}}</span><div><h3>{{spatialPointDetail.point.title}}</h3><p>{{spatialPointDetail.point.deviceName}} · X {{spatialPointDetail.point.xPercent}}% / Y {{spatialPointDetail.point.yPercent}}%</p></div></div><div class="detail-grid"><div><small>设备名称</small><b>{{spatialPointDetail.detail?.device?.craneName||spatialPointDetail.detail?.device?.deviceName||'-'}}</b></div><div><small>设备编号</small><b>{{spatialPointDetail.detail?.device?.craneNo||spatialPointDetail.detail?.device?.deviceNo||'-'}}</b></div><div><small>最新状态</small><b>{{tag(spatialPointDetail.detail?.latest?.status||'UNKNOWN')[0]}}</b></div><div><small>最新时间</small><b>{{formatDateTime(spatialPointDetail.detail?.latest?.collectedAt)}}</b></div></div><el-table :data="spatialPointDetail.detail?.alarms||[]" height="220"><el-table-column prop="alarmTime" label="预警时间" min-width="170"/><el-table-column prop="alarmType" label="类型"/><el-table-column prop="alarmLevel" label="等级"/><el-table-column prop="alarmMessage" label="内容" min-width="240"/><el-table-column label="状态"><template #default="{row}"><el-tag :type="tag(row.handleStatus)[1]">{{tag(row.handleStatus)[0]}}</el-tag></template></el-table-column></el-table></div><template #footer><el-button @click="spatialPointDetailDialog=false">关闭</el-button></template></el-dialog>
